<?php require_once __DIR__.'/../config/auth.php';require_admin();$popular=db()->query('SELECT l.titulo,COUNT(e.id) total FROM livros l LEFT JOIN emprestimos e ON e.livro_id=l.id GROUP BY l.id ORDER BY total DESC LIMIT 6')->fetchAll();$students=db()->query("SELECT u.nome,COUNT(e.id) total FROM usuarios u JOIN emprestimos e ON e.usuario_id=u.id WHERE u.tipo='aluno' GROUP BY u.id ORDER BY total DESC LIMIT 6")->fetchAll();$metrics=['Total de empréstimos'=>db()->query('SELECT COUNT(*) FROM emprestimos')->fetchColumn(),'Total de devoluções'=>db()->query("SELECT COUNT(*) FROM emprestimos WHERE status='devolvido'")->fetchColumn(),'Livros indisponíveis'=>db()->query('SELECT COUNT(*) FROM livros WHERE quantidade_disponivel=0')->fetchColumn()];$pageTitle='Relatórios';require __DIR__.'/../includes/header.php';require __DIR__.'/../includes/dashboard-nav.php';?><div class="dashboard-cards"><?php foreach($metrics as $title=>$value):?><div class="card metric"><span><?=e($title)?></span><b><?=$value?></b></div><?php endforeach;?></div><div class="dashboard-cards" style="margin-top:20px"><section class="panel" style="margin:0;grid-column:span 2"><h2>Livros mais emprestados</h2><div class="chart-bars"><?php foreach($popular as $i=>$p):?><i style="height:<?=max(12,min(100,$p['total']*18))?>%"><small><?=e(mb_strimwidth($p['titulo'],0,13,'…'))?></small></i><?php endforeach;?></div></section><section class="panel" style="margin:0"><h2>Alunos mais ativos</h2><?php foreach($students as $s):?><p><b><?=e($s['nome'])?></b><br><small class="subtext"><?=$s['total']?> empréstimo(s)</small></p><?php endforeach;?></section></div><?php require __DIR__.'/../includes/dashboard-footer.php';?>
